example.code:
{
  "product_name": "Trellis",
  "decided_on": "2026-07-20",
  "candidates": [
    {"name": "weekly teams completing at least one project", "counts": "value_event", "scores": {"customer_value": 5, "leading_indicator_of_revenue": 5, "actionable_within_quarter": 4, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 24},
    {"name": "weekly active teams", "counts": "mau", "scores": {"customer_value": 3, "leading_indicator_of_revenue": 3, "actionable_within_quarter": 4, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 20},
    {"name": "weekly signups", "counts": "signups", "scores": {"customer_value": 1, "leading_indicator_of_revenue": 2, "actionable_within_quarter": 5, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 18},
    {"name": "MRR", "counts": "revenue", "scores": {"customer_value": 2, "leading_indicator_of_revenue": 1, "actionable_within_quarter": 2, "understandable_without_data_team": 5, "measurable_today": 5}, "total": 15}
  ],
  "chosen_nsm": {"name": "weekly teams completing at least one project", "is_highest_scoring": true},
  "definition": {
    "events": ["project_completed"],
    "unit": "teams",
    "window": "weekly",
    "threshold": 1,
    "inclusions": ["free and paid workspaces", "projects with at least two members"],
    "exclusions": ["internal workspaces (domain trellis.example)", "test data flagged is_test", "workspaces created in the current week"],
    "dashboard_url": "https://analytics.example.com/dashboards/nsm-weekly-completing-teams"
  },
  "validation": {
    "method": "above_vs_below_threshold_cohort",
    "cohort_size": 4200,
    "period_start": "2026-05-01",
    "period_end": "2026-06-30",
    "outcome": "retained",
    "rate_above": 0.62,
    "rate_below": 0.21,
    "delta": 0.41,
    "result": "yes",
    "run_date": "2026-07-15"
  },
  "runner_ups": [
    {"name": "weekly active teams", "disposition": "input_metric"},
    {"name": "weekly signups", "disposition": "rejected", "rejection_reason": "can be bought with acquisition spend and says nothing about value received; loses on customer value and leading indicator"},
    {"name": "MRR", "disposition": "rejected", "rejection_reason": "lags value by months and is moved by pricing and packaging rather than by the product; kept as the outcome the NSM is validated against"}
  ],
  "input_metrics": [
    {"name": "weekly active teams", "dimension": "breadth", "owning_team": "growth", "current_value": 310, "target": 400, "movable_within_quarter": true},
    {"name": "projects completed per active team", "dimension": "depth", "owning_team": "product", "current_value": 1.8, "target": 2.5, "movable_within_quarter": true},
    {"name": "share of teams active on 3 or more days a week", "dimension": "frequency", "owning_team": "lifecycle", "current_value": 0.44, "target": 0.55, "movable_within_quarter": true},
    {"name": "median days from workspace creation to first completed project", "dimension": "efficiency", "owning_team": "onboarding", "current_value": 4.2, "target": 2.5, "movable_within_quarter": true}
  ],
  "gaming_risks": {
    "vectors": [
      {"vector": "notification_spam", "guard": {"kind": "paired_retention_metric", "detail": "week-8 team retention is reported next to the NSM; a rising NSM with flat retention triggers a review"}},
      {"vector": "internal_or_bot_activity", "guard": {"kind": "definition_exclusion", "detail": "internal workspaces and is_test data are excluded in the definition; projects completed by integration bots do not count"}},
      {"vector": "threshold_lowering", "guard": {"kind": "threshold_review_rule", "detail": "the threshold of one completed project changes only through a new decision record with a series-break date"}}
    ],
    "inflatable_by_spend_alone": false
  },
  "change_control": {"previous_record": null, "series_break_date": null, "next_review_date": "2027-07-15"}
}

